pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }

    function testFuzz_property(uint128 amount, bytes memory payload) public {
        uint256 amt = bound(amount, 0, 1 ether);

        Reverter rev = new Reverter();

        vm.deal(address(this), amt);

        bool ok;
        try c.Command{value: amt}(address(rev), payload) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
